import { PLUGIN_DIR, json, sharedSkills } from '../src/emit.mjs';

// Claude Code puts <plugin>/bin on the Bash tool's PATH while the plugin is enabled, so the skills' bare `go-getter <command>`
// runs the CLI copy bundled with go-getter-init instead of failing with "command not found" and sending the agent to guess.
const CLI_ENTRY = 'cli/compiler/bin/go-getter.mjs';
const SHIM = `#!/bin/sh
# Generated by go-getter build; do not edit. Runs the CLI bundled with the go-getter-init skill.
CLI="$(dirname "$0")/../skills/go-getter-init/cli/compiler/bin/go-getter.mjs"
if [ ! -f "$CLI" ]; then
  echo "go-getter: the bundled CLI is missing; reinstall the go-getter plugin" >&2
  exit 127
fi
if ! command -v node >/dev/null 2>&1; then
  echo "go-getter: Node.js is required to run the CLI; enforcement stays advisory until it is installed" >&2
  exit 127
fi
exec node "$CLI" "$@"
`;

export default (ctx) => ({
  ...sharedSkills(ctx),
  '.claude-plugin/marketplace.json': json({
    name: 'go-getter',
    owner: { name: 'vivantel' },
    description: ctx.meta.description,
    plugins: [{ name: 'go-getter', description: ctx.meta.description, source: `./${PLUGIN_DIR}` }],
  }),
  ...(ctx.skills.some((skill) => skill.files.includes(CLI_ENTRY)) ? { [`${PLUGIN_DIR}/bin/go-getter`]: { content: SHIM, mode: 0o755 } } : {}),
  [`${PLUGIN_DIR}/.claude-plugin/plugin.json`]: json({ ...ctx.meta, displayName: 'go-getter' }),
});
